/** Actual day/allocation/member and native old analysis baseline. Does not freeze INPUT or send analysis calls. */
class CatalogDayAnalysisInputPermitTest {
    boolean mysql(){return false;}
    CatalogDayAnalysisEligibilityTest outer(){return new CatalogDayAnalysisEligibilityTest(){@Override boolean mysql(){return CatalogDayAnalysisInputPermitTest.this.mysql();}};}
    record Built(CatalogDayAnalysisEligibilityTest outer,CatalogDayFullNativeIntegrationTest.Fixture f,CatalogDayAnalysisReservationLedger.Stored receipt){ }
    Built fresh(String category,boolean alias){var outer=outer();CatalogDayFullNativeIntegrationTest.Fixture f;if(alias){var aliases=new CatalogDayAliasEvidenceTest(){@Override boolean mysql(){return CatalogDayAnalysisInputPermitTest.this.mysql();}};f=aliases.new AliasFixture();}else f=outer.new NewFixture();f.terminal(category);f.completeSource();var selected=outer.eligibility(f).capture(outer.day).selected().getFirst();var helper=new CatalogDayAnalysisGenerationTest();var service=helper.service(outer,f,Clock.fixed(outer.completed.plusSeconds(90),ZoneOffset.UTC));return new Built(outer,f,service.reserve(outer.day,selected.entity().entityId()));}
    CatalogDayAnalysisInputPermitService provider(Built built){var outer=built.outer();var f=built.f();String category=f.f.category;var original=new CatalogDayAnalysisCommitPermitService(outer.evidence(f,Clock.fixed(outer.completed.plusSeconds(60),ZoneOffset.UTC)),f.graph.permits(),new JdbcSourceDayDedupClosures(f.f.source),f.f.tx,category);return new CatalogDayAnalysisInputPermitService(original,new CatalogDayAnalysisReservationLedger(new JdbcCatalogDayAnalysisReservations(f.f.source),category),new CatalogEntityAnalysisHeaderService(f.f.source,f.f.tx,category),new EntityInputEvidenceService(new JdbcEntityDedup(f.f.source),new SourceMemberEvidenceService(new JdbcSourceMemberEvidence(f.f.source))),f.graph.plans(),new CatalogVersionJudgmentLedger(new JdbcCatalogVersionJudgments(f.f.source),category),new JdbcFrozenSourcePlans(f.f.source),new JdbcJobRecords(f.f.source),new CatalogAnalysisContentBaselineService(f.f.source,f.f.tx,category),new CatalogPreviousAnalysisService(f.f.source,f.f.tx),new JdbcCatalogVersionJobFacts(f.f.source,category),f.f.tx,category);}
    @Test void FourCategoriesActualAllocatedNewEntityProvesWholeDayAndAbsentStableNativeTarget(){for(String category:List.of("agent","skill","workflow","model")){var built=fresh(category,false);var service=provider(built);var captured=service.capture(built.outer().day,built.receipt().entityId());assertEquals(built.receipt().json(),captured.receipt().json());assertEquals(1,captured.header().generation());assertEquals(built.receipt().entityRevisionAfter(),captured.header().revision());assertNull(captured.baseline());assertEquals(CatalogAnalysisContentBaselineService.newContentId(category,built.receipt().entityId()),captured.targetId());assertEquals(1,captured.entity().members().size());int jobs=built.f().f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class);assertSame(captured,built.f().write(()->service.verify(captured)));assertEquals(jobs,built.f().f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class));assertEquals(2,built.f().f.sends);assertFalse(captured.toString().contains("fictional"));}}
    @Test void ActualAliasPositiveIncludesAllOriginalBodiesAndFullOldNativeAnalysis(){for(String category:List.of("agent","skill","workflow","model")){var built=fresh(category,true);var service=provider(built);var captured=service.capture(built.outer().day,built.receipt().entityId());assertEquals(2,captured.entity().members().size());assertEquals(2,captured.entity().members().stream().map(CatalogDayEntityEvidenceService.Evidence::identityKey).distinct().count());assertEquals("fictional-analysis",captured.targetId());assertNotNull(captured.baseline());assertEquals(CatalogPreviousAnalysisTest.Fixture.ROOT,captured.baseline().inputRoot());assertEquals(1,captured.baseline().bodyRevision());assertSame(captured,built.f().write(()->service.verify(captured)));assertEquals(2,built.f().f.sends);}}
    @Test void OrdinaryEntityAndReviewRevisionsCanAdvanceButCapturedCasCannotBeReused(){var built=fresh("agent",true);var service=provider(built);var captured=service.capture(built.outer().day,built.receipt().entityId());built.f().f.jdbc.update("UPDATE analyzed_entities SET revision=revision+1");built.f().f.jdbc.update("UPDATE contents SET revision=revision+1");assertThrows(RuntimeException.class,()->built.f().write(()->service.verify(captured)));var fresh=service.capture(built.outer().day,built.receipt().entityId());assertEquals(captured.header().revision()+1,fresh.header().revision());assertEquals(captured.baseline().revision()+1,fresh.baseline().revision());assertEquals(captured.baseline().bodyRevision(),fresh.baseline().bodyRevision());assertSame(fresh,built.f().write(()->service.verify(fresh)));assertEquals(2,built.f().f.sends);}
    @Test void MissingReservationWrongIssuerAndRolesOrStaleHeaderRejectWholeCaller(){var built=fresh("workflow",false);var service=provider(built);var captured=service.capture(built.outer().day,built.receipt().entityId());assertThrows(RuntimeException.class,()->service.verify(captured));assertThrows(RuntimeException.class,()->built.outer().snapshot(built.f(),()->service.verify(captured)));assertThrows(RuntimeException.class,()->built.f().write(()->provider(built).verify(captured)));assertThrows(RuntimeException.class,()->built.outer().snapshot(built.f(),()->service.capture(built.outer().day,built.receipt().entityId())));long revision=captured.header().revision();assertThrows(RuntimeException.class,()->built.f().write(()->{built.f().f.jdbc.update("UPDATE analyzed_entities SET revision=revision+1");return service.verify(captured);}));assertEquals(revision,built.f().f.jdbc.queryForObject("SELECT revision FROM analyzed_entities",Long.class));built.f().f.jdbc.update("DELETE FROM jobs WHERE id=?",JdbcCatalogDayAnalysisReservations.id(built.receipt().reservationKey()));assertThrows(RuntimeException.class,()->service.capture(built.outer().day,built.receipt().entityId()));assertEquals(1,built.f().f.jdbc.queryForObject("SELECT analysis_generation FROM analyzed_entities",Integer.class));}
    @Test void CurrentOriginalMemberDamageAndNativePendingIntentNaturalIdentityDamageReject(){var built=fresh("skill",false);var service=provider(built);var captured=service.capture(built.outer().day,built.receipt().entityId());int jobs=built.f().f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class);assertThrows(RuntimeException.class,()->built.f().write(()->{built.f().f.jdbc.update("UPDATE source_run_items SET evidence_hash=?",new byte[32]);return service.verify(captured);}));assertThrows(RuntimeException.class,()->built.f().write(()->{built.f().f.jdbc.update("UPDATE jobs SET record_identity_hash=? WHERE id=?",new byte[32],built.receipt().intentId());return service.verify(captured);}));assertEquals(jobs,built.f().f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs",Integer.class));assertSame(captured,built.f().write(()->service.verify(captured)));assertEquals(2,built.f().f.sends);}
    @Test void OriginalOldAnalysisProofAndNativeContentChangeRejectAllLocks(){var built=fresh("model",true);var service=provider(built);var captured=service.capture(built.outer().day,built.receipt().entityId());assertThrows(RuntimeException.class,()->built.f().write(()->{built.f().f.jdbc.update("UPDATE jobs SET revision=revision+1 WHERE id=?",captured.baseline().inputRoot());return service.verify(captured);}));assertThrows(RuntimeException.class,()->built.f().write(()->{built.f().f.jdbc.update("UPDATE contents SET body_hash_v1=?",new byte[32]);return service.verify(captured);}));assertSame(captured,built.f().write(()->service.verify(captured)));built.f().f.jdbc.update("UPDATE contents SET input_job_id='fictional-wrong-root'");assertThrows(RuntimeException.class,()->service.capture(built.outer().day,built.receipt().entityId()));assertEquals(2,built.f().f.sends);}
    @Test void StartedOriginalIntentCannotGrantAnotherInputPreparation(){var built=fresh("agent",false);built.f().write(()->new JdbcJobRecords(built.f().f.source).createRoot(new JdbcJobRecords.Root("fictional-started-analysis",built.receipt().intentId(),built.receipt().logicalKey(),1,0,"agent_analysis",7),built.outer().completed.plusSeconds(91)));assertThrows(RuntimeException.class,()->provider(built).capture(built.outer().day,built.receipt().entityId()));assertEquals(1,built.f().f.jdbc.queryForObject("SELECT analysis_generation FROM analyzed_entities",Integer.class));assertEquals(2,built.f().f.sends);}
    @Test void MandatoryClosedCategoryProviderDoesNoIo(){var original=mock(CatalogDayAnalysisCommitPermitService.class);var reservations=mock(CatalogDayAnalysisReservationLedger.class);var headers=mock(CatalogEntityAnalysisHeaderService.class);var current=mock(EntityInputEvidenceService.class);var plans=mock(FrozenSourceStagePlanService.class);var judgments=mock(CatalogVersionJudgmentLedger.class);var owners=mock(JdbcFrozenSourcePlans.class);var records=mock(JdbcJobRecords.class);var contents=mock(CatalogAnalysisContentBaselineService.class);var previous=mock(CatalogPreviousAnalysisService.class);var jobs=mock(JdbcCatalogVersionJobFacts.class);var tx=mock(PlatformTransactionManager.class);for(String category:List.of("agent","skill","workflow","model"))assertNotNull(new CatalogDayAnalysisInputPermitService(original,reservations,headers,current,plans,judgments,owners,records,contents,previous,jobs,tx,category));verifyNoInteractions(original,reservations,headers,current,plans,judgments,owners,records,contents,previous,jobs,tx);assertThrows(RuntimeException.class,()->new CatalogDayAnalysisInputPermitService(original,reservations,headers,current,plans,judgments,owners,records,contents,previous,jobs,tx,"news_tech"));}
}
